import subprocess, tempfile, os
def fmt(txt):
    r=subprocess.run(["/workspace/executable","--stdin","--noconfig"], input=txt, capture_output=True, text=True)
    return r.stdout

# So blank lines are collapsed to at most one empty line? Actually n=1,2,3,4 all collapse to single blank line (one empty line) between content.
# For plain n=0 => no blank, n=1,2,3 => single blank.
# So formatter normalizes blank lines: collapses multiple consecutive blank lines into one, but preserves single blank.
# What about blank at start/end? 
print(repr(fmt("
\begin{document}
hello
\end{document}
")))
print(repr(fmt("\begin{document}
hello
\end{document}


")))
print(repr(fmt("

\begin{document}
hello
\end{document}


")))

# Check handling of trailing newline at EOF: we saw earlier file without newline still got newline added. Blank at end collapsed? Let's see file without trailing newline after \end{document} but with blank?
# The formatter always ends with single newline, not multiple.
print(repr(fmt("\begin{document}
hello
\end{document}")))  # no newline
print(repr(fmt("\begin{document}
hello
\end{document}

")))  # extra newline

# Check handling of lines that are comments alone: indent for comment lines inside env? Earlier inside itemize, comment line was indented 4 spaces (visual 2) while \item was 2. So comment lines inside list get visual 2 (not 1). What about comment inside document? Document not indent, so comment 0.
print(fmt("\begin{document}
% comment
hello
\end{document}
"))
print(fmt("\begin{itemize}
% comment
\item hello
\end{itemize}
"))

# Check handling of \item with no content: earlier we saw \item newline hello gave indent for hello as continuation (visual 2)
print(repr(fmt("\begin{itemize}
\item
hello
\end{itemize}
")))
# Check handling of multiple \item on same line? Probably splits.
print(repr(fmt("\begin{itemize}
\item hello \item world
\end{itemize}
")))
