def find_config_file(explicit_path, use_noconfig):
    if explicit_path:
        # Use explicit path even if noconfig
        if not os.path.exists(explicit_path):
            eprint(f"thread 'main' panicked at src/config.rs:83:63:")
            eprint(f"called `Result::unwrap()` on an `Err` value: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}")
            sys.exit(101)
        # Try to parse, if fails, panic
        try:
            with open(explicit_path, "rb") as f:
                import tomli
                tomli.load(f)
        except Exception:
            eprint(f"thread 'main' panicked at src/config.rs:119:9:")
            eprint(f"Failed to read config file at {explicit_path}")
            sys.exit(101)
        return explicit_path
    if use_noconfig:
        return None
    # Search order: cwd tex-fmt.toml, git root tex-fmt.toml, user config
    cwd = os.getcwd()
    # 1. cwd
    p = os.path.join(cwd, "tex-fmt.toml")
    if os.path.exists(p):
        return p
    # 2. git root
    try:
        # Use git rev-parse --show-toplevel
        result = subprocess.run(["git","rev-parse","--show-toplevel"], capture_output=True, text=True, cwd=cwd)
        if result.returncode == 0:
            git_root = result.stdout.strip()
            if git_root:
                p2 = os.path.join(git_root, "tex-fmt.toml")
                if os.path.exists(p2):
                    return p2
    except:
        pass
    # 3. user config
    # Linux: ~/.config/tex-fmt/tex-fmt.toml
    # Also check XDG_CONFIG_HOME?
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg:
        p3 = os.path.join(xdg, "tex-fmt", "tex-fmt.toml")
        if os.path.exists(p3):
            return p3
    home = os.path.expanduser("~")
    p3 = os.path.join(home, ".config", "tex-fmt", "tex-fmt.toml")
    if os.path.exists(p3):
        return p3
    # macOS: ~/Library/Application Support/tex-fmt/tex-fmt.toml
