    opts = {
        "check": False,
        "print": False,
        "fail_on_change": False,
        "wrap": True,
        "wraplen": None,
        "tabsize": None,
        "usetabs": False,
        "stdin": False,
        "config": None,
        "noconfig": False,
        "verbose": False,
        "quiet": False,
        "trace": False,
        "completion": None,
        "man": False,
        "args": False,
        "recursive": False,
        "help": False,
        "version": False,
    }
    files = []
