        if arg.startswith("--completion="):
            val = arg.split("=",1)[1]
            if val == "":
                error_missing("--completion")
            if val not in ["bash","elvish","fish","powershell","zsh"]:
                error_invalid_completion(val)
            opts["completion"] = val
