def get_indent_string(visual, tabsize, tabchar):
    cnt = visual * tabsize
    if tabchar == "tab":
        return "\t" * cnt
    else:
        return " " * cnt

def env_weight(env, lists, no_indent_envs, verbatims):
    if env in no_indent_envs:
        return 0
    if env in verbatims:
        return 0
    if env in lists:
        return 2
    return 1

def detect_env(line):
    res=[]
    for m in re.finditer(r'\\(begin|end)\s*\{([^}]*)\}', line):
        res.append((m.group(1), m.group(2).strip(), m.start(), m.end()))
    return res

def split_line_for_envs(line):
    lines=[line]
    changed=True
    iterations=0
    while changed and iterations<10:
        changed=False
        new_lines=[]
        for l in lines:
            stripped=l.lstrip()
            if stripped=="":
                new_lines.append(l)
                continue
            leading=len(l)-len(stripped)
            content=stripped
            envs=detect_env(content)
            if not envs:
                new_lines.append(l)
                continue
            first_type, first_name, s, e = envs[0]
            if s>0:
                before=content[:s].rstrip()
                if before.strip()!="":
                    new_lines.append(" " * leading + before)
                    rest=content[s:]
                    # Check trailing after first env
                    env_end=e
                    trailing=content[env_end:].strip()
                    if trailing!="":
                        env_token=content[s:env_end]
                        new_lines.append(env_token)
                        new_lines.append(trailing)
                    else:
                        new_lines.append(content[s:])
                    changed=True
                    continue
            # No preceding, check trailing
            env_end=e
            trailing=content[env_end:].strip()
            if trailing!="":
                env_token=content[:env_end]
                new_lines.append(env_token)
                new_lines.append(trailing)
                changed=True
                continue
            if len(envs)>1:
                second_s=envs[1][2]
                before_second=content[:second_s].rstrip()
                if before_second.strip()!="":
                    new_lines.append(before_second)
                    new_lines.append(content[second_s:])
                    changed=True
                    continue
            new_lines.append(l)
        if changed:
            lines=new_lines
        iterations+=1
    return lines

def format_text(text, config, log_fn=None):
    tabsize=config["tabsize"]
    tabchar=config["tabchar"]
    wraplen=config["wraplen"]
    wrapmin=config["wrapmin"]
    do_wrap=config["wrap"]
    lists=config["lists"]
    verbatims=config["verbatims"]
    no_indent_envs=config["no_indent_envs"]
    wrap_chars=config["wrap_chars"]

    if text=="":
        return "\n"
    has_trailing_nl=text.endswith("\n")
    parts=text.split("\n")
    if has_trailing_nl and parts and parts[-1]=="":
        lines_input=parts[:-1]
    else:
        lines_input=parts

    stack=[]
    verbatim_depth=0
    off=False
    output_lines=[]
    pending_env_split=[]

    def total_weight(stk):
        return sum(env_weight(env, lists, no_indent_envs, verbatims) for env in stk)

    # For trace, need line numbers
    input_line_no=0
    output_line_no=0

    for raw_line in lines_input:
        input_line_no+=1
        stripped_raw=raw_line.strip()
        # Handle tex-fmt: off/on/skip
        if "% tex-fmt: off" in raw_line:
            off=True
            output_lines.append(raw_line)
            if log_fn:
                log_fn("TRACE", f"Line {input_line_no} ({output_line_no+1}). Indent: actual = 0, visual = 0: {raw_line}")
            continue
        if "% tex-fmt: on" in raw_line:
            off=False
            output_lines.append(raw_line)
            continue
        if "% tex-fmt: skip" in raw_line:
            output_lines.append(raw_line)
            continue
        if off:
            output_lines.append(raw_line)
            continue
        is_blank=(stripped_raw=="")
        if is_blank:
            output_lines.append("")
            continue

        # Verbatim handling: check if inside verbatim
        if verbatim_depth>0:
            active=None
            for env in reversed(stack):
                if env in verbatims:
                    active=env
                    break
            if active and re.search(r'\\end\s*\{\s*'+re.escape(active)+r'\s*\}', raw_line):
                # End of verbatim
                if active in stack:
                    idx=len(stack)-1-stack[::-1].index(active)
                    stack.pop(idx)
                    verbatim_depth-=1
                # Fall through to normal handling for this line (the \end line itself)
            else:
                output_lines.append(raw_line)
                continue

        # Split line for envs
        sublines=split_line_for_envs(raw_line)
        for sub in sublines:
            sub_stripped=sub.strip()
            if sub_stripped=="":
                output_lines.append("")
                continue
            env_match_begin=re.search(r'\\begin\s*\{([^}]*)\}', sub)
            env_match_end=re.search(r'\\end\s*\{([^}]*)\}', sub)
            is_begin=env_match_begin is not None
            is_end=env_match_end is not None
            env_name=None
            if is_begin:
                env_name=env_match_begin.group(1).strip()
            elif is_end:
                env_name=env_match_end.group(1).strip()

            if is_end and env_name is not None:
                found=-1
                for idx in range(len(stack)-1,-1,-1):
                    if stack[idx]==env_name:
                        found=idx
                        break
                if found!=-1:
                    stack.pop(found)
                    if env_name in verbatims:
                        verbatim_depth=max(0, verbatim_depth-1)
                visual=total_weight(stack)
                indent_str=get_indent_string(visual, tabsize, tabchar)
                if log_fn:
                    log_fn("TRACE", f"Line {input_line_no} ({output_line_no+1}). Indent: actual = {visual}, visual = {visual}: {sub_stripped}")
                output_lines.append(indent_str+sub_stripped)
                output_line_no+=1
                continue
            if is_begin and env_name is not None:
                visual=total_weight(stack)
                indent_str=get_indent_string(visual, tabsize, tabchar)
                if log_fn:
                    log_fn("TRACE", f"Line {input_line_no} ({output_line_no+1}). Indent: actual = {visual}, visual = {visual}: {sub_stripped}")
                output_lines.append(indent_str+sub_stripped)
                output_line_no+=1
                stack.append(env_name)
                if env_name in verbatims:
                    verbatim_depth+=1
                continue
            # Content line
            total_w=total_weight(stack)
            is_item=sub_stripped.startswith("\\item")
            if is_item and any(e in lists for e in stack):
                visual=max(0, total_w-1)
            else:
                visual=total_w
            indent_str=get_indent_string(visual, tabsize, tabchar)
            if log_fn:
                log_fn("TRACE", f"Line {input_line_no} ({output_line_no+1}). Indent: actual = {visual}, visual = {visual}: {sub_stripped}")
            content=sub_stripped
            full_len=len(indent_str)+len(content)
            # Wrapping
            if not do_wrap or full_len <= wraplen:
                output_lines.append(indent_str+content)
                output_line_no+=1
                continue
            # Wrap needed
            if log_fn:
                log_fn("TRACE", f"Line {input_line_no} ({output_line_no+1}). Wrapping long line. {content}")
            cont_visual=total_w
            cont_indent=get_indent_string(cont_visual, tabsize, tabchar)
            remaining=content
            first=True
            while True:
                indent_cur=indent_str if first else cont_indent
                max_len=wraplen - len(indent_cur)
                min_len=wrapmin - len(indent_cur)
                if len(remaining)+len(indent_cur) <= wraplen:
                    if log_fn:
                        log_fn("TRACE", f"Line {input_line_no} ({output_line_no+1}). Indent: actual = {cont_visual if not first else visual}, visual = {cont_visual if not first else visual}: {remaining}")
                    output_lines.append(indent_cur+remaining)
                    output_line_no+=1
                    break
                substr=remaining[:max_len]
                last_space=substr.rfind(" ")
                last_wrap=-1
                for wc in wrap_chars:
                    idx=substr.rfind(wc)
                    if idx!=-1:
                        pos=idx+len(wc)
                        if pos>last_wrap and pos<=max_len:
                            last_wrap=pos
                break_pos=-1
                is_wrap=False
                if last_space!=-1 and last_space>=min_len:
                    break_pos=last_space
                elif last_wrap!=-1 and last_wrap>=min_len:
                    break_pos=last_wrap
                    is_wrap=True
                else:
                    if last_space!=-1:
                        break_pos=last_space
                    elif last_wrap!=-1:
                        break_pos=last_wrap
                        is_wrap=True
                    else:
                        break_pos=-1
                if break_pos==-1:
                    # cannot wrap
                    if log_fn:
                        log_fn("WARN", f"Line {input_line_no} ({output_line_no+1}). Line cannot be wrapped. {remaining}")
                    output_lines.append(indent_cur+remaining)
                    output_line_no+=1
                    break
                if is_wrap:
                    first_part=remaining[:break_pos].rstrip()
                    remaining=remaining[break_pos:].lstrip()
                else:
                    first_part=remaining[:break_pos].rstrip()
                    remaining=remaining[break_pos+1:].lstrip()
                if log_fn:
                    log_fn("TRACE", f"Line {input_line_no} ({output_line_no+1}). Indent: actual = {visual if first else cont_visual}, visual = {visual if first else cont_visual}: {first_part}")
                output_lines.append(indent_cur+first_part)
                output_line_no+=1
                first=False
                continue

    # Post-process blanks
    while output_lines and output_lines[-1]=="":
        output_lines.pop()
    new_out=[]
    blank_cnt=0
    for idx, line in enumerate(output_lines):
        if line=="":
            blank_cnt+=1
            if idx<2:
                if blank_cnt<=2:
                    new_out.append(line)
            else:
                if blank_cnt==1:
                    new_out.append(line)
        else:
            blank_cnt=0
            new_out.append(line)
    output_lines=new_out
    if not output_lines:
        return "\n"
    return "\n".join(output_lines)+"\n"

