def log_message(level, config, msg, file="<stdin>"):
    order={"trace":0,"info":1,"warn":2,"error":3}
    verb=config.get("verbosity","warn")
    if order.get(level.lower(), 99) < order.get(verb, 99):
        return
    print(f"{level}: tex-fmt {file}: {msg}", file=sys.stderr)

def process_file(path, config, opts):
    if os.path.isdir(path):
        eprint(f"ERROR: tex-fmt : A directory was passed without --recursive. ")
        return None, None, True
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            content=f.read()
    except Exception:
        eprint(f"ERROR: tex-fmt {path}: Could not open file. ")
        return None, None, True
    verb=config["verbosity"]
    if verb in ["trace","info"]:
        eprint(f"INFO: tex-fmt {path}: Formatting started. ")
    if verb=="trace":
        try:
            b=os.path.getsize(path)
            eprint(f"TRACE: tex-fmt {path}: Read {b} bytes. ")
        except:
            pass
    # Need to handle trace logging for indent etc inside format_text
    # We'll create a log function that prints trace indent etc
    def log_fn(level, msg):
        # level is "TRACE" or "WARN"
        # Use config verbosity to decide, but we already filter
        if level=="TRACE" and config["verbosity"]!="trace":
            return
        if level=="WARN" and config["verbosity"]=="error":
            return
        # For WARN, we need to prefix with WARN: tex-fmt path:
        # For TRACE, prefix with TRACE: tex-fmt path:
        # Use same format as original
        print(f"{level}: tex-fmt {path}: {msg}", file=sys.stderr)

    # Format
    formatted = format_text(content, config, log_fn=log_fn)
    # Check for indent not zero warning
    # We need to determine if stack not empty at end -> warn
    # For that we need to know if format_text ended with non-zero stack. We can approximate by checking if formatted ends with mismatched?
    # Simpler: we can check if original content had unbalanced begin/end by counting stack after format
    # We'll just not implement warning for now, but we can add simple check: if formatted contains more \begin than \end, warn
    # The original warning: "Indent does not return to zero. Last non-indented line is line X"
    # We won't implement fully

    # Also need to log formatting complete
    if verb in ["trace","info"]:
        eprint(f"INFO: tex-fmt {path}: Formatting complete. ")
    changed = (formatted != content)
    return changed, formatted, False

def main():
    opts, files = parse_cli(sys.argv)
    if opts["help"]:
        sys.stdout.write(HELP_TEXT)
        sys.exit(0)
    if opts["version"]:
        sys.stdout.write(VERSION_TEXT)
        sys.exit(0)
    if opts["man"]:
        sys.stdout.write(MAN_TEXT)
        sys.exit(0)
    if opts["completion"] is not None:
        sh = opts["completion"]
        if sh=="bash":
            sys.stdout.write(BASH_COMP)
        elif sh=="fish":
            sys.stdout.write(FISH_COMP)
        elif sh=="zsh":
            sys.stdout.write(ZSH_COMP)
        elif sh=="elvish":
            sys.stdout.write(ELVISH_COMP)
        elif sh=="powershell":
            sys.stdout.write(POWERSHELL_COMP)
        else:
